-- =========================================================
-- Final Deathknell Val'kyr hardening / cleanup pass
-- Purpose:
--   * keep Aradne's waypoint path 192759 intact on reruns
--   * raise Daschla and Aradne higher above terrain
--   * enforce airborne template state for the four Val'kyr
--   * clean obvious emote/anim overrides that fight hover/fly visuals
-- Notes:
--   * If you start Aradne's path from C++ (MovePath(192759, false)), restart worldserver after apply.
--   * Waypoint data for 192759 is present later in this file; this block avoids deleting it unnecessarily.
-- =========================================================

-- Force airborne template settings for all four Val'kyr
UPDATE creature_template
SET InhabitType = 4,
    HoverHeight = CASE entry
        WHEN 49044 THEN 6.0  -- Agatha
        WHEN 49128 THEN 8.0  -- Daschla
        WHEN 49129 THEN 6.5  -- Arthura
        WHEN 50372 THEN 7.0  -- Aradne
        ELSE HoverHeight
    END
WHERE entry IN (49044, 49128, 49129, 50372);

-- Raise problem spawns that were clipping into the ground
UPDATE creature
SET position_z = CASE guid
    WHEN 192760 THEN 120.621994018554673  -- Daschla raised +6.0 from imported placement
    WHEN 192759 THEN 141.813980102539062  -- Aradne raised +4.0 from imported placement
    ELSE position_z
END
WHERE guid IN (192760, 192759);

-- Reassert Aradne addon state explicitly for C++-controlled pathing
UPDATE creature_addon
SET path_id = 0,
    AnimTier = 3,
    emote = 0,
    aiAnimKit = 0,
    movementAnimKit = 0,
    meleeAnimKit = 0
WHERE guid = 192759;

-- Improve airborne visual defaults for the four Val'kyr
UPDATE creature_addon
SET AnimTier = 3,
    emote = 0,
    aiAnimKit = 0,
    movementAnimKit = 0,
    meleeAnimKit = 0
WHERE guid IN (192768, 192760, 192757, 192759);

-- Remove text-emote overrides that can knock them out of their fly/hover look
UPDATE creature_text
SET Emote = 0
WHERE CreatureID IN (49044, 49128, 49129, 50372);

-- Aradne path start is controlled from C++, not DB auto-movement
UPDATE creature
SET MovementType = 0,
    wander_distance = 0
WHERE guid = 192759;


