-- =========================================================
-- Arthura restore
-- Real live DB setup:
--   * spawn guid = 192757
--   * entry = 49129
--   * MovementType = 2
--   * path is template-level, not spawn-level
--   * creature_template_addon.path_id = 3250850
--   * waypoint nodes live in waypoint_data.id = 3250850
-- =========================================================

SET @ARTHURA_GUID := 192757;
SET @ARTHURA_ENTRY := 49129;
SET @ARTHURA_PATH := 3250850;

-- Keep Arthura on her known-good live spawn and enable waypoint movement
UPDATE `creature`
SET
    `position_x` = 1733.34,
    `position_y` = 1647.83,
    `position_z` = 129.265,
    `orientation` = 0.928349,
    `wander_distance` = 0,
    `currentwaypoint` = 0,
    `MovementType` = 2
WHERE `guid` = @ARTHURA_GUID
  AND `id` = @ARTHURA_ENTRY;

-- Arthura uses template-level pathing.
-- Do NOT bind a spawn-level path here.
DELETE FROM `creature_addon`
WHERE `guid` = @ARTHURA_GUID;

-- Enforce the correct template-level addon/path state for Arthura
DELETE FROM `creature_template_addon`
WHERE `entry` = @ARTHURA_ENTRY;

 `aiAnimKit`, `movementAnimKit`, `meleeAnimKit`, `visibilityDistanceType`, `auras`)
VALUES
(@ARTHURA_ENTRY, @ARTHURA_PATH, 0, 0, 3, 0, 1, 0, 0, 0, 0, 0, 0, '');

-- Arthura has a plain waypoint loop: no delays, no waypoint scripts
DELETE FROM `waypoint_data`
WHERE `id` = @ARTHURA_PATH;


COMMIT;